+            "foo where \"abc\": \"*b\"",
+            "foo where \"abc\": \"b*\""
+        );
+
+        // string comparison that evaluates to false
+        for (String q : tests) {
+            LogicalPlan plan = accept(q);
+            assertTrue(plan instanceof LocalRelation);
+        }
