+            return this;
+        }
+
+        public Builder setLargestWaitingAnomalyJob(Long largestWaitingAnomalyJob) {
+            this.largestWaitingAnomalyJob = largestWaitingAnomalyJob;
+            return this;
+        }
+
+        public Builder setCurrentMlCapacity(AutoscalingCapacity currentMlCapacity) {
