+                if (parent == null) {
+                    parentBitSet = parentFilter;
+                    parentNameLength = 0;
+                } else {
+                    if (objectFilters.containsKey(parent) == false) {
+                        throw new IllegalStateException("Cannot find parent mapper for path " + path + " in doc " + doc);
+                    }
