+            // we do not need compile-only dependencies here
+            if (compileOnlyArtifacts.contains(dep.getGroup() + ":" + dep.getName() + ":" + dep.getVersion())) {
+                continue;
+            }
+
+            // only external dependencies are checked
+            if (dep instanceof ProjectDependency) {
+                continue;
+            }
