+            GroupConfig groupConfig = (GroupConfig) args[1];
+            @SuppressWarnings("unchecked")
+            List<MetricConfig> metricsConfig = (List<MetricConfig>) args[2];
+            TimeValue timeout = (TimeValue) args[3];
