+74999.0
+;
+
+selectWithGroupByCountAndOrderBy
+SELECT salary_ul AS s, count(1) AS c FROM test_emp_copy GROUP BY 1 ORDER BY 1 LIMIT 3;
+
+       s:ul    |       c:l
+---------------+---------------
+25324          |1
+25945          |1
+25976          |1
+;
+
+selectWithMathFunction
