+class CancellableRateLimitedFluxIterator<T> implements Subscriber<T>, Iterator<T> {
+    private static final Subscription CANCELLED_SUBSCRIPTION = new Subscription() {
+        @Override
+        public void request(long n) {
+            // no op
+        }
+
+        @Override
+        public void cancel() {
+            // no op
+        }
+    };
