+    public void cancel() {
+        cancelSubscription();
+        clearQueue();
+        done = true;
+        // cancel should be called from the consumer
+        // thread, but to avoid potential deadlocks
+        // we just try to release a possibly blocked
+        // consumer
+        signalConsumer();
+    }
+
+    @Override
+    public void onError(Throwable t) {
+        clearQueue();
+        error = t;
+        done = true;
+        signalConsumer();
+    }
+
+    @Override
+    public void onComplete() {
+        done = true;
+        signalConsumer();
+    }
